import icontract


@icontract.require(lambda n: n >= 0)
@icontract.ensure(lambda result: result >= 0)
@icontract.ensure(lambda n, result: 15 * result == n * (2 * n + 1) * (7 + 24 * n ** 3 - 12 * n ** 2 - 14 * n))
def sumOfFourthPowerOfOddNumbers(n: int) -> int:
    result = 0
    for i in range(n):
        odd = 2 * i + 1
        result += odd ** 4
    return result
